function ajustarTelefone(raw) {
  if (!raw) return null;
  let t = raw.toString().replace(/\D/g, "");
  if (t.length === 10 || t.length === 11) t = "55" + t;
  return t;
}

return items
  .map(item => ({
    json: {
      ...item.json,
      telefonePadronizado: ajustarTelefone(item.json.telefone || item.json.whatsapp)
    }
  }))
  .filter(i => i.json.telefonePadronizado && i.json.telefonePadronizado.length >= 12);

// =====================================================================
// DECIDE O AGENTE
// ---------------------------------------------------------------------
// Objetivo: para CADA lead, decidir qual "agente" (ou seja, qual número
// de WhatsApp / conta da Meta) deve disparar o reminder da reunião.
//
// Existem 4 agentes possíveis: inbound, remarketing, parceiros e advisor.
// Cada um tem seu próprio phone_number_id, whatsapp_business_id e a chave
// de memória no Redis. A saída deste node alimenta o switch que roteia o
// lead para o calendário/fluxo do agente certo.
//
// ORDEM DE PRIORIDADE (o primeiro que "casar" vence):
//   1. Histórico  -> qual agente falou POR ÚLTIMO com esse lead.
//                    É a fonte de verdade mais confiável: se já existe
//                    conversa, respeitamos o número que já vinha atendendo.
//   2. dono_do_lead = 47 -> advisor.
//                    ATENÇÃO: advisor e inbound compartilham o MESMO
//                    midia_id (14). Mídia não distingue os dois; o que
//                    distingue é o dono do lead. Por isso esta checagem
//                    vem ANTES da mídia — senão todo advisor viraria
//                    inbound no passo 3.
//   3. midia_id do mailing -> quando não há histórico nem dono advisor:
//                    15 = remarketing | 14 = inbound | 2 = parceiros
//   4. Default    -> se nada casou, assume inbound.
// =====================================================================

// Lead atual (o fluxo roda 1 lead por vez via "Rodar lembrete por lead").
const lead = $('Preparar variáveis do lead').first().json;

// ---------------------------------------------------------------------
// Catálogo dos agentes: todos os dados de identidade de cada número.
// Manter tudo aqui centraliza a configuração — se um número/ID mudar,
// altera-se só neste objeto.
// ---------------------------------------------------------------------
const AGENTES = {
  inbound: {
    agente: 'inbound',
    nome_app: 'SDR-INBOUND',
    phone_number_id: '1292568043938721',
    whatsapp_business_id: '1540465040616348',
    redis_suffix: '_mem_agent_FINAMOB_SDR_INBOUND'
  },

  remarketing: {
    agente: 'remarketing',
    nome_app: 'SDR-REMARKETING',
    phone_number_id: '1202871396233612',
    whatsapp_business_id: '1017599083929094',
    redis_suffix: '_mem_agent_FINAMOB_SDR'
  },

  parceiros: {
    agente: 'parceiros',
    nome_app: 'SDR-PARCEIROS',
    phone_number_id: '1374636505725573',
    whatsapp_business_id: '1080464844460481',
    redis_suffix: '_mem_agent_FINAMOB_SDR_PARCEIROS'
  },

  advisor: {
    agente: 'advisor',
    nome_app: 'SDR-ADVISOR',
    phone_number_id: '1195821910283433',
    whatsapp_business_id: '1422925556340455',
    redis_suffix: '_mem_agent_FINAMOB_SDR_ADVISOR'
  }
};

// Valor de dono_do_lead que marca o braço advisor (Gabriel).
const DONO_ADVISOR = '47';


// ---- 1. HISTÓRICO (maior prioridade) --------------------------------
// "items" traz o resultado do node anterior (última mensagem no
// histórico desse lead). Se já houve conversa, o nome_app dessa última
// mensagem diz qual agente já estava atendendo — e é ele que respeitamos.
let origem = 'historico';   // rótulo p/ debug: de onde veio a decisão
let escolhido = null;       // agente escolhido (null até alguém casar)

// Pega o json da última mensagem, se existir.
const hist = items && items.length ? items[0].json : null;

// Normaliza o nome_app do histórico (trim + maiúsculas) p/ comparar.
const nomeAppHist = hist && hist.nome_app
  ? String(hist.nome_app).trim().toUpperCase()
  : null;

// Mapeia o nome_app do histórico direto para o agente correspondente.
if (nomeAppHist === 'SDR-REMARKETING') {
  escolhido = AGENTES.remarketing;

} else if (nomeAppHist === 'SDR-INBOUND') {
  escolhido = AGENTES.inbound;

} else if (nomeAppHist === 'SDR-PARCEIROS') {
  escolhido = AGENTES.parceiros;

} else if (nomeAppHist === 'SDR-ADVISOR') {
  escolhido = AGENTES.advisor;
}


// ---- 1.b DONO DO LEAD = advisor -------------------------------------
// Só entra aqui se o histórico NÃO resolveu (lead sem conversa anterior).
// Como advisor e inbound têm o mesmo midia_id (14), a única forma de
// identificar advisor sem histórico é pelo dono do lead. Por isso este
// bloco precisa vir ANTES da checagem de midia_id (passo 2).
if (!escolhido) {
  const dono = String(lead.dono_do_lead ?? '').trim();

  if (dono === DONO_ADVISOR) {
    origem = 'dono_do_lead';
    escolhido = AGENTES.advisor;
  }
}


// ---- 2. MIDIA_ID ----------------------------------------------------
// Fallback quando não há histórico e o lead não é advisor por dono.
// Classifica pelo canal de origem do mailing.
if (!escolhido) {
  origem = 'midia_id';

  const midia = String(lead.midia_id ?? '').trim();

  if (midia === '15') {
    escolhido = AGENTES.remarketing;

  } else if (midia === '14') {
    escolhido = AGENTES.inbound;   // (advisor já foi tratado no passo 1.b)

  } else if (midia === '2') {
    escolhido = AGENTES.parceiros;
  }
}


// ---- 3. DEFAULT -----------------------------------------------------
// Rede de segurança: se nada casou (mídia desconhecida/nula), assume
// inbound para nunca deixar o lead sem agente.
if (!escolhido) {
  origem = 'default_inbound';
  escolhido = AGENTES.inbound;
}


// ---- RETORNO --------------------------------------------------------
// Devolve todos os dados do agente escolhido + campos auxiliares.
// - origem_decisao / nome_app_historico: rastro de COMO foi decidido
//   (ótimo para depurar por que um lead foi parar em determinado agente).
// - dono_do_lead / advisor_responsavel_id / midia_id: repassados adiante
//   (o filtro do braço advisor usa o advisor_responsavel_id lá na frente).
return [{
  json: {
    ...escolhido,
    origem_decisao: origem,
    nome_app_historico: nomeAppHist,
    midia_id: lead.midia_id ?? null,
    dono_do_lead: lead.dono_do_lead ?? null,
    advisor_responsavel_id: lead.advisor_responsavel_id ?? null,
    telefone: lead.telefone,
    lead_nome: lead.name
  }
}];

const lead = $('Preparar variáveis do lead').first().json;
const agente = $('Decide o agente').first().json;

const nome = (lead.name || '').trim().split(' ')[0] || 'tudo bem';

const TEMPLATE = {
  name: 'remarcar_no_show',
  text: 'Oi, {{1}}! Vi que não conseguimos nos falar na reunião. Quer que eu te passe uns horários pra gente remarcar?'
};

const texto = TEMPLATE.text.replace('{{1}}', nome);

return [{
  json: {
    resultado_api: {
      messaging_product: 'whatsapp',
      to: lead.telefone,
      type: 'template',
      template: {
        name: TEMPLATE.name,
        language: { code: 'pt_BR' },
        components: [{ type: 'body', parameters: [{ type: 'text', text: nome }] }]
      }
    },
    mensagem_visual: texto,
    redis_memory_message: JSON.stringify({
      type: 'ai',
      data: { content: texto, tool_calls: [], invalid_tool_calls: [], additional_kwargs: {}, response_metadata: {} }
    }),
    template_name: TEMPLATE.name,
    nome_app: agente.nome_app,
    phone_number_id: agente.phone_number_id
  }
}];

